class Solution {
public:
    int partitionString(std::string s) {
        int mask = 0;
        int count = 1;
        for (char ch : s) {
            int bit = 1 << (ch - 'a');
            if (mask & bit) {
                count++;
                mask = bit;
            } else {
                mask |= bit;
            }
        }
        return count;
    }
};

class Solution {
    public int partitionString(String s) {
        int mask = 0;
        int count = 1;
        for (int i = 0; i < s.length(); i++) {
            int bit = 1 << (s.charAt(i) - 'a');
            if ((mask & bit) != 0) {
                count++;
                mask = bit;
            } else {
                mask |= bit;
            }
        }
        return count;
    }
}

var partitionString = function(s) {
    let mask = 0;
    let count = 1;
    for (let i = 0; i < s.length; i++) {
        const bit = 1 << (s.charCodeAt(i) - 97);
        if ((mask & bit) !== 0) {
            count++;
            mask = bit;
        } else {
            mask |= bit;
        }
    }
    return count;
};
